<?php
namespace Tests\Feature;
use App\Jobs\ModerateProductImage;
use App\Models\Category; use App\Models\ModerationScan; use App\Models\Product; use App\Models\ProductImage; use App\Models\Report; use App\Models\Role; use App\Models\SellerProfile; use App\Models\Store; use App\Models\User; use App\Services\Moderation\ImageModerationService; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Storage; use Tests\TestCase;
class ModerationWorkflowTest extends TestCase { use RefreshDatabase;
 public function test_flagged_image_creates_report_and_human_can_confirm_false_positive():void { Storage::fake('public');$superRole=Role::create(['name'=>'Super Admin','slug'=>'super_admin','guard_name'=>'web']);$sellerRole=Role::create(['name'=>'Seller','slug'=>'seller','guard_name'=>'web']);$super=User::factory()->create(['is_active'=>true]);$super->assignRole($superRole);$seller=User::factory()->create(['is_active'=>true]);$seller->assignRole($sellerRole);$profile=SellerProfile::create(['user_id'=>$seller->id,'status'=>'approved']);$store=Store::create(['user_id'=>$seller->id,'seller_profile_id'=>$profile->id,'name'=>'Safe Shop','slug'=>'safe-shop','status'=>'active']);$category=Category::create(['name'=>'Test','slug'=>'test']);$product=Product::create(['store_id'=>$store->id,'category_id'=>$category->id,'name'=>'Review Item','slug'=>'review-item','price'=>100,'stock'=>2,'is_active'=>true]);Storage::disk('public')->put('products/review.png','fake-image');$image=ProductImage::create(['product_id'=>$product->id,'path'=>'products/review.png','is_primary'=>true]);$scan=ModerationScan::create(['product_id'=>$product->id,'product_image_id'=>$image->id,'seller_id'=>$seller->id,'store_id'=>$store->id,'provider'=>'fake','status'=>'pending_scan']);$fake=new class implements ImageModerationService { public function scan(string $path):array{return ['status'=>'flagged','category'=>'weapon','confidence'=>.92,'risk_level'=>'high','reference'=>'fake-1'];}};(new ModerateProductImage($scan->id))->handle($fake);$this->assertDatabaseHas('moderation_scans',['id'=>$scan->id,'status'=>'flagged','detected_category'=>'weapon']);$this->assertDatabaseHas('reports',['target_type'=>Product::class,'target_id'=>$product->id,'source'=>'automated_moderation','priority'=>'high']);$this->assertFalse($product->fresh()->is_active);$this->actingAs($super)->post(route('superadmin.moderation.review',$scan),['decision'=>'false_positive','notes'=>'Human review found no violation.'])->assertSessionHasNoErrors();$this->assertTrue($product->fresh()->is_active);$this->assertSame('approved',$product->fresh()->moderation_status);$this->assertDatabaseCount('violations',0); }
 public function test_buyer_can_report_product_once():void { $buyer=User::factory()->create(['is_active'=>true]);$seller=User::factory()->create(['is_active'=>true]);$profile=SellerProfile::create(['user_id'=>$seller->id,'status'=>'approved']);$store=Store::create(['user_id'=>$seller->id,'seller_profile_id'=>$profile->id,'name'=>'Shop','slug'=>'shop','status'=>'active']);$category=Category::create(['name'=>'Test','slug'=>'test']);$product=Product::create(['store_id'=>$store->id,'category_id'=>$category->id,'name'=>'Item','slug'=>'item','price'=>10,'stock'=>1]);$this->actingAs($buyer)->post(route('products.report',$product),['reason'=>'incorrect_listing','description'=>'The product details do not match the image.'])->assertSessionHasNoErrors();$this->assertDatabaseHas('reports',['reporter_id'=>$buyer->id,'target_id'=>$product->id,'reason'=>'incorrect_listing']); }
}
